    "{role} automatically has every permission, including any added in future.": "{role} کو خود بخود ہر اختیار حاصل ہے، آئندہ شامل ہونے والے اختیارات سمیت۔",
    "Data scope": "ڈیٹا کا دائرہ",
    "{scope} decides whose records a role covers: the whole institution, the classes the person teaches, or only their own.": "{scope} طے کرتا ہے کہ کردار کن ریکارڈز تک رسائی رکھتا ہے: پورا ادارہ، وہ کلاسیں جنہیں یہ فرد پڑھاتا ہے، یا صرف اس کا اپنا ریکارڈ۔",
    "Data scope — whose records this role covers": "ڈیٹا کا دائرہ — یہ کردار کن ریکارڈز تک رسائی رکھتا ہے",
    "You can only give or take away permissions you hold yourself. Nobody but the Super Admin can change the role they hold.": "آپ صرف وہی اختیارات دے یا لے سکتے ہیں جو خود آپ کے پاس ہوں۔ سپر ایڈمن کے سوا کوئی اپنا کردار تبدیل نہیں کر سکتا۔",
    "Admin, Teacher and Student cannot be deleted. A custom role can be deleted once nobody holds it.": "ایڈمن، استاذ اور طالب علم کے کردار حذف نہیں ہو سکتے۔ اضافی کردار اس وقت حذف ہو سکتا ہے جب کسی کے پاس نہ ہو۔",
