    // Institutional heritage
    "Institutional Heritage & History": "ادارے کی تاریخ و ورثہ",
    "Historical background, founding legacy, leadership lineage, and branch network of Ashrafia Islamic University Lahore": "جامعہ اشرفیہ لاہور کا تاریخی پس منظر، قیام، قیادت کا سلسلہ اور شاخوں کا نیٹ ورک",
