    "Year Founded": "سالِ قیام",
    "120 Kanals": "۱۲۰ کنال",
    "Main Campus Land": "مرکزی کیمپس کا رقبہ",
    "Campuses & Branches": "کیمپس و شاخیں",
    "Over 2,000+": "دو ہزار سے زائد",
    "Academic Board": "تعلیمی بورڈ",
    "Founding & Campus Expansion": "قیام و توسیع",
    "Spiritual & Academic Lineage": "روحانی و علمی سلسلہ",
    "Branch Network (12 Regional Campuses)": "شاخوں کا نیٹ ورک (۱۲ علاقائی کیمپس)",
    "Lahore & Rawalpindi": "لاہور و راولپنڈی",
    "Branch Name": "شاخ کا نام",
    "Location": "مقام",
    "Est. Year": "سالِ قیام",
    "Student Strength": "طلبہ کی تعداد",
    "{x} Campus": "{x} کیمپس",
    "Women's Campus": "خواتین کیمپس",
    "Main Academic": "مرکزی تعلیمی",
    "Connected to LMS": "ایل ایم ایس سے منسلک",
    "Ashrafia Free Charitable Hospital": "اشرفیہ فری خیراتی ہسپتال",
    "In addition to sacred scholarship, Jamia Ashrafia operates a full-service charitable hospital on Ferozepur Road, providing free diagnostics, outpatient care, emergency treatments, and essential medicines to thousands of underprivileged citizens daily.": "دینی تعلیم کے ساتھ ساتھ جامعہ اشرفیہ فیروزپور روڈ پر ایک مکمل خیراتی ہسپتال چلاتا ہے، جہاں روزانہ ہزاروں مستحق افراد کو مفت تشخیص، او پی ڈی، ہنگامی علاج اور ضروری ادویات فراہم کی جاتی ہیں۔",
    "Maktaba Ashrafia & Darul Ifta": "مکتبہ اشرفیہ و دارالافتاء",
    "Maktaba Ashrafia maintains tens of thousands of rare classical Islamic manuscripts, Hadith compendiums, and Fatawa volumes. Its Darul Ifta is an internationally trusted authority rendering authoritative Shariah guidance on contemporary Islamic banking, bioethics, and family law.": "مکتبہ اشرفیہ میں دسیوں ہزار نادر قدیم اسلامی مخطوطات، حدیث کے مجموعے اور فتاویٰ کی جلدیں محفوظ ہیں۔ اس کا دارالافتاء ایک بین الاقوامی سطح پر معتبر ادارہ ہے جو جدید اسلامی بینکاری، طبی اخلاقیات اور عائلی قوانین پر مستند شرعی رہنمائی فراہم کرتا ہے۔",
    "Founded on <strong>14 September 1947</strong>, just one month following the independence of Pakistan, Jamia Ashrafia was established by the eminent scholar <strong>Hazrat Maulana Mufti Muhammad Hassan Amritsari (RA)</strong>. In recognition of the immense spiritual guidance and unwavering support for an independent Muslim homeland, the institution was named in honor of the revered Hakim al-Ummah <strong>Hazrat Maulana Ashraf Ali Thanwi (RA)</strong>.": "قیامِ پاکستان کے صرف ایک ماہ بعد <strong>۱۴ ستمبر ۱۹۴۷ء</strong> کو جید عالمِ دین <strong>حضرت مولانا مفتی محمد حسن امرتسریؒ</strong> نے جامعہ اشرفیہ کی بنیاد رکھی۔ آزاد اسلامی وطن کے لیے عظیم روحانی رہنمائی اور غیر متزلزل حمایت کے اعتراف میں ادارے کا نام حکیم الامت <strong>حضرت مولانا اشرف علی تھانویؒ</strong> کے نام پر رکھا گیا۔",
    "<strong>Nila Gumbad Anarkali (1947):</strong> Jamia Ashrafia commenced in a historic three-storied quadrangular building at Nila Gumbad in the vibrant historic center of Lahore. The initial classes quickly attracted seekers of sacred knowledge from across the subcontinent.": "<strong>نیلا گنبد انارکلی (۱۹۴۷ء):</strong> جامعہ اشرفیہ کا آغاز لاہور کے پُررونق تاریخی مرکز نیلا گنبد میں ایک تاریخی سہ منزلہ چوکور عمارت میں ہوا۔ ابتدائی درجات نے جلد ہی پورے برصغیر سے علمِ دین کے متلاشیوں کو اپنی طرف متوجہ کر لیا۔",
    "<strong>Ferozepur Road Campus (1955-1957):</strong> On <strong>28 March 1955</strong>, a sprawling 120-kanal estate situated between Canal Road and Ferozepur Road was acquired. Construction began with the laying of the foundation stone for the central Grand Jamia Mosque. By 1957, the faculty and residential students relocated to this majestic new campus.": "<strong>فیروزپور روڈ کیمپس (۱۹۵۵ء-۱۹۵۷ء):</strong> <strong>۲۸ مارچ ۱۹۵۵ء</strong> کو کینال روڈ اور فیروزپور روڈ کے درمیان ۱۲۰ کنال کا وسیع رقبہ حاصل کیا گیا۔ مرکزی جامع مسجد کے سنگِ بنیاد سے تعمیر کا آغاز ہوا، اور ۱۹۵۷ء تک اساتذہ اور مقیم طلبہ اس شاندار نئے کیمپس میں منتقل ہو گئے۔",
    "<strong>Faculty of Hadith (1958):</strong> Teaching of classical Hadith courses was formally inaugurated in 1958 under the globally celebrated Muhaddith <strong>Hazrat Maulana Muhammad Idris Kandhlawi (RA)</strong>, author of <em>Ma'arif al-Quran</em> and <em>At-Ta'liq as-Sabih</em>.": "<strong>شعبۂ حدیث (۱۹۵۸ء):</strong> ۱۹۵۸ء میں عالمی شہرت یافتہ محدث <strong>حضرت مولانا محمد ادریس کاندھلویؒ</strong>، مصنف <em>معارف القرآن</em> و <em>التعلیق الصبیح</em>، کی سرپرستی میں دورۂ حدیث کی باقاعدہ تدریس کا آغاز ہوا۔",
    "Following the passing of the founder <strong>Mufti Muhammad Hassan</strong> on 1 June 1961, institutional leadership and preservation of high academic standards were carried forward by his distinguished sons:": "یکم جون ۱۹۶۱ء کو بانی <strong>مفتی محمد حسنؒ</strong> کی وفات کے بعد ادارے کی قیادت اور اعلیٰ علمی معیار کی حفاظت ان کے ممتاز صاحبزادوں نے سنبھالی:",
    "<strong>Maulana Mufti Muhammad Ubaidullah (Late):</strong> Pioneered international academic outreach.": "<strong>مولانا مفتی محمد عبید اللہؒ:</strong> بین الاقوامی علمی روابط کے بانی۔",
    "<strong>Maulana Abd-ur-Rahman Ashrafi (Late):</strong> Champion of community welfare and education.": "<strong>مولانا عبدالرحمٰن اشرفیؒ:</strong> سماجی بہبود اور تعلیم کے علمبردار۔",
    "<strong>Maulana Fazl-ur-Raheem Ashrafi:</strong> Current Principal / Mohtamim, leading modern reforms and the Cloud LMS initiative.": "<strong>مولانا فضل الرحیم اشرفی:</strong> موجودہ مہتمم، جدید اصلاحات اور کلاؤڈ ایل ایم ایس منصوبے کے سربراہ۔",
    "<strong>Maulana Hafiz Ajwad Ubaid & Qari Arshad Ubaid:</strong> Guiding academic administration and Hadith discourse.": "<strong>مولانا حافظ اجود عبید و قاری ارشد عبید:</strong> تعلیمی انتظام اور درسِ حدیث کے نگران۔",
    "<strong>Wifaq ul Madaris Equivalence:</strong> The <em>Shahadat-ul-Alimiyyah</em> degree awarded by Jamia Ashrafia under Wifaq-ul-Madaris Al-Arabia Pakistan is recognized by the Higher Education Commission (HEC) of Pakistan as equivalent to an M.A. in Islamic Studies and Arabic.": "<strong>وفاق المدارس کی مساوات:</strong> وفاق المدارس العربیہ پاکستان کے تحت جامعہ اشرفیہ کی عطا کردہ <em>شہادۃ العالمیہ</em> کو ہائر ایجوکیشن کمیشن (HEC) پاکستان اسلامیات و عربی میں ایم اے کے مساوی تسلیم کرتا ہے۔",

