    "The free public {service} service ends embedded calls after 5 minutes, so classes on it open in a new tab (no time limit). If you run your own Jitsi server or an 8x8 JaaS account, enter its domain and tick \"embed\" to show classes inside the portal.": "مفت عوامی {service} سروس پورٹل کے اندر کالز ۵ منٹ بعد ختم کر دیتی ہے، اس لیے اس پر کلاسیں نئے ٹیب میں کھلتی ہیں (کوئی وقت کی حد نہیں)۔ اگر آپ کا اپنا Jitsi سرور یا 8x8 JaaS اکاؤنٹ ہے تو اس کا ڈومین درج کریں اور پورٹل کے اندر کلاسیں دکھانے کے لیے \"embed\" منتخب کریں۔",
    "Jitsi server domain": "Jitsi سرور ڈومین",
    "Embed the classroom inside the portal (own Jitsi server / JaaS only)": "کلاس روم پورٹل کے اندر دکھائیں (صرف اپنا Jitsi سرور / JaaS)",
    "Save Classroom Service": "کلاس روم سروس محفوظ کریں",
    "Storage Maintenance & Emergency Purge": "اسٹوریج کی دیکھ بھال و ہنگامی صفائی",
    "Run an immediate storage audit across the {count} recorded lectures. Any recordings exceeding the {days}-day retention threshold will be permanently pruned from cloud buckets and database records updated.": "{count} ریکارڈ شدہ دروس کی فوری جانچ کریں۔ {days} دن کی حد سے پرانی ریکارڈنگز کلاؤڈ سے مستقل طور پر حذف ہو جائیں گی اور ڈیٹا بیس ریکارڈ اپ ڈیٹ ہو جائیں گے۔",
    "Important Preservation Note:": "اہم نوٹ برائے حفاظت:",
    "Master lectures flagged with {flag} (such as Takhassus Fiqh Seminar) are permanently exempted from automated deletion cycles.": "{flag} والے بنیادی دروس (جیسے تخصص فقہ سیمینار) خودکار حذف سے ہمیشہ مستثنیٰ رہتے ہیں۔",
