    "Are you sure you want to execute storage cleanup? Any recordings exceeding the configured retention cycle will be permanently deleted.": "کیا آپ واقعی اسٹوریج کی صفائی کرنا چاہتے ہیں؟ مقررہ مدت سے پرانی تمام ریکارڈنگز مستقل طور پر حذف ہو جائیں گی۔",
