    "You are not allowed to open or close exams.": "آپ کو امتحانات کھولنے یا بند کرنے کی اجازت نہیں۔",
    "You are not allowed to write exam papers.": "آپ کو امتحانی پرچے تیار کرنے کی اجازت نہیں۔",
    "You are not allowed to verify payments.": "آپ کو ادائیگیوں کی تصدیق کی اجازت نہیں۔",
